import {abilityNames,abilityDescriptions,characterAbilityIds,savedCharacterAbilities,rarityForAbilities,abilityMaximums,savedCharacterPotential,characterStartingRarity} from './character-stats.js';
import {displayName} from './identity.js';
const abilityEsc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function characterStatsContent(state){
 const known=characterAbilityIds.filter(id=>id==='taei'||state.contacts?.[id]?.introduced);
 return `<p class="ability-intro">힘·민첩·체력·인내·정신력은 기본 능력이에요. 숫자는 현재 능력 / 개인 성장 한계예요. 현재 포만감·수분·공포·부상은 생존 화면에서 따로 확인해요.</p><p class="ability-note">${state.characterSystem?'새 플레이의 등장 인물은 시작할 때 정해져요. 장소를 다시 열어도 바뀌지 않아요.':'이 저장은 기존 등장 인물과 생존 규칙을 유지해요. 아래 값은 새 게임부터 적용되는 기본 능력이에요.'}</p><details class="ability-guide"><summary>능력치의 뜻과 평균 범위</summary><p>힘·민첩은 성인 남성 평균2~5, 성인 여성 평균1~4를 참고해요. 개인의 운동 경험과 체격에 따라 평균을 넘을 수 있어요.</p>${Object.entries(abilityNames).map(([key,name])=>`<p><strong>${name}</strong> · ${abilityDescriptions[key]}</p>`).join('')}<p>힘·민첩은 전체 상한20, 체력·인내·정신력은50이며 각 인물의 성장 한계는 따로 있어요. 수치 옆 분모는 그 인물의 성장 한계예요. 인내와 정신력이 높아도 물·음식·치료가 필요해요. 희소성은 능력치 합계로 정하며, 인간성이나 동료가 될 가능성을 뜻하지 않아요.</p></details>${known.map(id=>{const stats=savedCharacterAbilities(state,id),rarity=characterStartingRarity(state,id),potential=savedCharacterPotential(state,id);return `<article class="ability-card" data-stats-character="${id}"><header><h2>${abilityEsc(displayName(state,id))}</h2><span class="ability-rarity">출현 희소성 · ${rarity.label}</span></header><dl class="ability-grid">${Object.entries(abilityNames).map(([key,name])=>`<div><dt>${name}</dt><dd>${stats[key]}<small>/${potential[key]}</small></dd><meter aria-label="${name}" min="0" max="${potential[key]}" value="${stats[key]}"></meter></div>`).join('')}</dl><p>${id==='taei'?'기본 주인공으로 항상 등장해요.':`새 플레이의 출현 배정 확률 ${Math.round(rarity.probability*100)}% · 실제 만남은 일정과 행동에 따라 달라져요.`}</p></article>`;}).join('')}<p class="ability-note">직접 소개받은 인물의 기본 능력만 표시해요. 활동과 생존 역할을 수행하면 경험이 쌓이고 개인 한계까지 천천히 성장해요.</p>`;
}
